"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[354],{1792:(e,t,a)=>{a.d(t,{Te:()=>i,km:()=>s});var n=a(1463);n.env.NEXT_PUBLIC_SITE_URL;let o=n.env.NEXT_PUBLIC_MAIL_INTAKE_DOMAIN??"findfunding.ai",i=`support@${o}`,s="findfunding.ai is not a lender or a loan broker. We do not make credit decisions, quote rates, or promise approval. Any grant, loan or offer shown is one you may apply for; the funder decides. You review and submit; it never submits for you."},2450:(e,t,a)=>{a.d(t,{default:()=>h});var n=a(5155),o=a(8500),i=a.n(o),s=a(2115),r=a(3105),d=a(9373);function h({className:e="text-sm"}){let[t,a]=(0,s.useState)(!1),[o,u]=(0,s.useState)("/login");return((0,s.useEffect)(()=>{a((0,r.wR)());let e=window.location.pathname;u(e&&"/"!==e&&"/login"!==e?`/login?next=${encodeURIComponent(e)}`:"/login")},[]),t)?(0,n.jsx)(d.A,{className:e}):(0,n.jsx)(i(),{href:o,"data-testid":"header-signin",className:`accent-action min-h-11 inline-flex shrink-0 items-center whitespace-nowrap ${e}`.trim(),children:"Sign in"})}},2538:(e,t,a)=>{a.d(t,{h:()=>i,z:()=>o});var n=a(2115);let o=(0,n.createContext)(!1),i=()=>(0,n.useContext)(o)},7855:(e,t,a)=>{a.d(t,{A:()=>s});var n=a(5155),o=a(3321),i=a(3105);function s({className:e=""}){let t=(0,o.useRouter)();return(0,n.jsx)("button",{type:"button",onClick:()=>{(0,i.q0)(),t.push("/login")},className:`quiet-link min-h-11 inline-flex shrink-0 items-center whitespace-nowrap ${e}`.trim(),children:"Sign out"})}},8373:(e,t,a)=>{a.d(t,{F1:()=>s});var n=a(1792),o=a(1463);let i=n.Te,s="findfunding.ai is not a lender or a broker. We do not make credit decisions, quote rates, or promise approval. Any grant, loan or offer shown is one you may apply for; the funder decides.",r=[{id:"ai-output",heading:"What the AI produces",paragraphs:["Uploaded documents are read by automated analysis to fill your profile.","What the AI produces. Our software uses AI to read your documents and draft summaries, fields, and matches. AI systems make mistakes, including confident ones. Everything the software fills in is shown to you before it is used or sent anywhere, and you are responsible for checking it. Nothing the AI produces is advice (not legal, tax, accounting, or credit advice), and nothing it produces is an offer, an approval, or a decision by any lender or grantor."],source:"G-AI-2, legal-surface-uat-2026-08-24.md (verbatim)."},{id:"what-we-are-not",heading:"What findfunding.ai is not",paragraphs:[s],source:"F1, compliance-posture-v1.md \xa7Strings (verbatim)."},{id:"estimates",heading:"Estimates, not offers",paragraphs:["Estimated fit, not an offer or approval. Based only on what you told us and this lender’s published criteria. The lender decides after its own review; terms may differ."],source:"S1, compliance-posture-v1.md \xa7Strings (verbatim)."},{id:"alpha-waiver",heading:"Alpha Edition waiver (alpha-w1b-2026-10-12)",note:{text:"This is the text of the Alpha Edition waiver, printed here so you can read it. It is written in the first person because it is worded as a statement a person makes when they sign it. Reading it on this page is not signing it. Nothing on this page records an agreement, and this site has nowhere to store one. If we ever ask you to agree to it, we will ask you plainly, on a screen with a box you tick yourself, and we will keep a record of the version you agreed to.",source:'Half B (i), dav-09-10-sections-2026-09-21.md section 3.1 (lending-compliance, Warren), verbatim. Publish verdict: section 4 table of that file, row B, "PUBLISH TONIGHT, and it is the most urgent item in this file". Placement and the testId are section 3.2 of that file. NOT from W1: the paragraphs below are W1, this line is not, and the section source must not be read as covering it.',testId:"waiver-not-executed"},paragraphs:["findfunding.ai Alpha Edition: what I’m agreeing to.","I’m accepting an invitation to the private alpha of findfunding.ai. I understand this is unfinished software: it will have bugs, it may lose or mangle data, features will change, and it may be taken down without notice.","I understand findfunding.ai uses AI services run by third-party providers, today OpenAI, to read and organise what I give it: the documents I upload, what I type, and public records about my business. I understand findfunding.ai uses those providers under subscription accounts rather than business data-processing contracts, so it has no retention terms and no no-training terms of its own to show me, and that it cannot guarantee what any provider does inside its own systems. My information is handled as described in the privacy policy, which I have read.","I understand AI output can be wrong, that I am shown what was extracted before it is used, and that checking it is on me.","I understand findfunding.ai is not a lender or a broker. It does not make credit decisions, quote rates, or promise approval. Anything it shows me is an estimated fit based on what I told it, not an offer and not an approval. The funder decides."],source:"W1 as revised 2026-10-12 (alpha-w1b-2026-10-12), from W1, legal-surface-uat-2026-08-24.md (verbatim; signature block omitted) with paragraph 3 corrected. The 2026-08-24 paragraph named Anthropic and asserted a no-training election; basis for the correction is files/security/luna-upload-privacy-audit-2026-10-12.md sections 2 and 3.2. Lending-compliance and counsel to accept, amend or reject."},{id:"accounts",heading:"Your account",paragraphs:["You need an account to use findfunding.ai, and the account is yours. Keep the password to yourself, and tell us straight away if you think someone else has got into it.","Give us real information. Everything the site does for you is built on what you tell it about your business, so a wrong answer produces a wrong result, and a set-aside program checked against an ownership answer that is not true is a problem for you and not for us.","findfunding.ai is for finding funding for a business. It is not a place to look for a personal loan, a mortgage, or credit for household or family use.","You should be old enough to enter into a contract where you live, and you should be entitled to act for the business you are searching on behalf of.","One account is one person. If two people at the same business each want in, each of you should have your own."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT, with one check, in that file's section 4 table."},{id:"acceptable-use",heading:"What you may and may not do here",paragraphs:["Use the site for its purpose: finding funding you might actually apply for.","Do not upload documents that are not yours to upload, or anyone else's financial information without their say-so.","Do not scrape the site, copy the funding database out of it, or resell what you find here as your own product.","Do not try to get into other people's accounts or other people's data, and do not probe, overload, or attack the service.","Do not use the site to break the law, to defraud a funder, or to put false information in front of a lender or a grant program.","If any of that happens we can suspend or close the account, and if it is serious we will do it without warning. Where we can give you notice first, we will.","We built this for small businesses and we run it for small businesses. If something here is getting in your way, write to us before you work around it."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT in that file's section 4 table."},{id:"fees",heading:"Fees and referrals",paragraphs:["The alpha is free. There is no charge to use findfunding.ai today: no subscription, no fee per application, and no cut of anything you raise.","We are not paid by funders to show you their programs. No lender, bank, or grant program pays us to appear in your results, and none of them pays for where they appear. What you see is what we found, in the order we think fits you.","That is true today and we will not change it quietly. If we ever take money from a funder in connection with sending you to them, we will tell you on the screen where it matters, before you act on it, and we will say who pays us and what for.","If we ever start charging you, we will tell you what it costs before you owe anything, and using the site up to that point will never create a bill you did not agree to.","We are not a broker and we do not take a success fee. We will not charge you a percentage of funding you receive."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT in that file's section 4 table."},{id:"termination",heading:"Pausing or closing your account",paragraphs:["You can stop using findfunding.ai whenever you like, and you can ask us to close your account and delete what is in it. Write to the address at the bottom of this page.","We can suspend or close an account if it is being used in one of the ways the previous section rules out, if we are required to, or if we stop running the service.","Except where something serious or unlawful is happening, we will tell you before we close your account and give you a chance to get your information out.","This is unfinished software in an early alpha. We may change it, take features away, or stop running it. If we shut it down, we will give you notice and a way to take your information with you.","Closing your account ends your access. What we keep afterwards, and for how long, is described in the privacy policy."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT in that file's section 4 table."},{id:"liability",heading:"Who is responsible if something goes wrong",paragraphs:["findfunding.ai shows you funding programs you might fit and helps you get organised to apply. It does not decide anything. The funder decides, every time.","Nothing here is legal, tax, accounting, or financial advice, and nothing here is an offer, an approval, or a promise of money.","The software uses AI, AI gets things wrong, and it gets things wrong confidently. We show you what it read and where it read it, and checking it before you rely on it is on you.","This is an alpha. It will have bugs, it may lose or mangle what you put in it, and it can go down without warning. We are telling you that plainly rather than burying it."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim, paragraphs 1 to 4 of 6. Paragraphs 5 and 6 (limitation of liability and its severability partner) are HELD for licensed review per that file's section 2.5 and its section 4 row 10; they are absent from this array rather than summarised, and adding them later needs no rewrite of these four."},{id:"governing-law",heading:"Which law applies, and how disagreements are settled",paragraphs:[`This part is not written yet. We would rather leave it blank than put up a rule we cannot stand behind. If you need an answer it should have given you, write to ${i} and a person will write back.`],source:"No ruled copy exists. Honest minimum — lending-compliance to extend.",thin:!0},{id:"changes",heading:"Changes to these terms",paragraphs:["These terms will change while the product is being built. The date at the top of this page is the version you are reading.","When something significant changes, we will say so rather than swapping the page out quietly, and we will keep the older versions available.","During the alpha we do not treat carrying on using the site as you agreeing to a new version. If we need your agreement to something, we will ask for it properly, on a screen, with a box you tick yourself.","If you do not want to continue under a change, stop using the site and ask us to close your account."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT in that file's section 4 table."}];[...(function(e,t="true"===o.env.NEXT_PUBLIC_SITE_LAUNCHED){return t?e.filter(e=>!e.devPhaseOnly):e})([{id:"ai-processing",heading:"How we use AI on your information",paragraphs:["AI processing. We use artificial-intelligence services run by third-party providers to read and organise what you give us: documents you upload, answers you type, and public records about your business. The provider we use for that work today is OpenAI; we may use others, the list can change as we build, and what we use for your documents is set out at /fine-print/documents.","We use these providers under subscription accounts rather than business data-processing contracts, so we have no retention terms and no no-training terms of our own to show you, and we are not going to print a number here that we cannot stand behind. We cannot audit a provider’s systems and we do not promise you what any provider does inside them. If we obtain written terms, we will say so here with the date we obtained them.","We send these providers only what is needed to do the work in front of us. We do not sell your information, and we do not send it to a lender or any other funder unless you pick that funder and say yes."],source:"G-AI-1-V2, 2026-10-12. Replaces G-AI-1 (legal-surface-uat-2026-08-24.md), which named Anthropic on a lane that ships to OpenAI and claimed a no-training election we do not hold. Basis: files/security/luna-upload-privacy-audit-2026-10-12.md sections 2 and 3.3, with lending-compliance and counsel to accept, amend or reject. Same posture as the served consent strings G-AI-3-V2 and R1-V2 (services/consent_strings.py)."},{id:"dev-mode",devPhaseOnly:!0,heading:"Addendum: Dev Mode",paragraphs:["findfunding.ai is still being built, and while we build it we run many AI models from many different companies, switching between them as we test. Some of what passes through those models may end up being used to train them. We don’t know, and we won’t pretend otherwise. We have made our best efforts to keep your information private and secure even while we test, and if you would rather nothing of yours goes through them yet, type your figures in instead of uploading, or write to us and we will delete what you have given us."],source:"Owner ruling, Stephen 2026-10-13 12:59 ET (Dev Mode addendum, his draft polished by Marketing \xb7 Godin seat). Consistent with the 2026-08-24 ruling: the privacy surface discloses, never guarantees (memory/builds/2026-08-24.md:129). Visible 'TODO: Remove Before Launch' marker removed 2026-10-24: the 2026-10-13 ruling adopted it as a code comment and launch-checklist row, not page text."},{id:"what-we-are-not",heading:"What findfunding.ai is not",paragraphs:[s],source:"F1, compliance-posture-v1.md \xa7Strings (verbatim)."},{id:"consent-upload",heading:"What you are asked to consent to",paragraphs:["When you upload a document, this is the consent you give:","To fill in your profile, the text of this document is sent to OpenAI, an outside company whose AI model reads it and returns the figures it finds. We mask Social Security, bank account and card numbers before we send, and we check every figure the model returns against your document so nothing invented reaches your profile. Your EIN, your business and personal names, addresses, and the financial figures on the page are sent as they are printed. We send no name, account or file name of ours with it. We use OpenAI under a subscription account, not a business data-processing contract, so we cannot promise you how long they keep what we send or whether it is used to improve their models; we tell you that plainly rather than quote you a number we cannot stand behind. Your document is held on our own server, reachable only by this service and the people who run it. You see everything we extract before it goes anywhere, nothing is shared with a lender unless you choose one and say yes, and uploading a document does not mean you have applied for anything or been approved for anything. If you would rather no outside company read it, you can skip the upload and type your figures in yourself.","When we preload public records about your business, this is added to that consent:","…and I understand AI services run by third-party providers, today OpenAI, may be used to read and organise those records, on the terms set out at /fine-print/documents."],source:"U1-A3 (consent_strings.U1_A3, CONSENT_VERSION u1-a3-r1v2-2026-10-12) and P1-A2. P1-A2 replaced P1-A on 2026-10-12 for the same reason U1-A3 replaced U1-A: the retired line named Anthropic, which is refused by name on this lane. P1-A is quoted on this page only and is recorded against no consent hash, so it is corrected in place rather than retired into SUPERSEDED_CONSENTS. U1-A3 replaced U1-A on 2026-10-12: the retired text named Anthropic on a path that ships to OpenAI and claimed the document was stored encrypted. Draft prose from files/security/luna-upload-privacy-audit-2026-10-12.md section 3.3, with lending-compliance and counsel to accept, amend or reject. Quoted here verbatim from the served string."},{id:"alpha-edition",heading:"Alpha Edition",paragraphs:["findfunding.ai is an invite-only private Alpha Edition. The terms of that alpha (what unfinished software means, how AI reads what you give us, and that nothing here is an approval) are set out in the Alpha Edition waiver, reproduced in full in our Terms. Please read it; it describes the deal you are in."],source:"Option B wording, verbatim from ff-legal-pages-complete-draft-2026-09-11.md \xa73.3 (compliance seat), adopted as the interim truth-fix under \xa73.4; alpha framing from the governing ruling (Stephen, 2026-08-24) in legal-surface-uat-2026-08-24.md; the waiver itself (W1) is rendered verbatim on /terms."},{id:"what-we-collect",heading:"What we collect",paragraphs:["Four kinds of information reach us, and you can see all four.","What you give us to open an account. Your email address, a username, a password we store only as a scrambled value we cannot read back, and your name if you choose to add it.","What you tell us about your business. Its legal name and trading name, where it is, how it is set up, how long it has been going, roughly how many people work there, its revenue and other figures you type in, what you want the money for, and identifiers like a NAICS code or a SAM UEI if you have them.","Some funding programs are set aside for businesses with particular ownership, for example veteran-owned, woman-owned or minority-owned. There is a field where you can tell us. We can also end up holding the same thing without you filling that field in: from a certification you add to your profile, or from words in your business name, your web address or your profile keywords that say the business is owned that way. However we come to hold it, we use it to check the ownership criteria that set-aside programs publish, and to decide whether to ask you about it. It changes nothing about a program that does not publish an ownership criterion. Where a program does publish one, this is what we check you against, so it can change where that program sits in your list. You can leave it blank and still use everything here.","Documents you upload. Tax returns, profit and loss statements, bank statements, and anything else you choose to send us. We read them to fill in your profile, we show you every value we pulled out and the page it came from, and nothing goes onto your profile until you confirm it.","Public records about your business. Before you arrive and while you use the site we look at information that is already public, for example a company registration or your own website, so you are not retyping what the world already knows.","How the site is used. Ordinary technical records that any website keeps: the pages requested, the time, the browser, and the network address the request came from. We use these to keep the site working and to stop abuse."],source:"DAV-09 section 1.1 paragraph 4, amended by lending-compliance ruling W-OWN-1 (2026-09-22); dav-09-10-sections-2026-09-21.md (verbatim)."},{id:"retention",heading:"How long we keep it",paragraphs:["While your account is open we keep what you have given us, because that is the thing the site is for.","A file you upload but do not keep is discarded when you say so, and the file itself is gone.","A file you have kept and then delete has its contents and every fact read from it destroyed. A short record that a document existed and was deleted on a particular day survives so we can answer what happened.","We also keep a record of the consents you gave, including the exact wording you were shown and when. We keep those after the thing they authorised is gone, because that record is the only way either of us can later show what you were actually told.","During the alpha nothing is deleted automatically on a timer. We have not set a fixed period, and rather than publish a number we do not enforce we are telling you plainly that there is not one yet. When we set one, it will appear here and we will tell you before it starts.","Ask us to delete your account and what is in it, and we will. Write to the address at the bottom of this page.","If the alpha ends, we will tell you before anything is removed and give you a way to take your information with you first."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT in that file's section 4 table."},{id:"your-choices",heading:"Your choices, and asking us for things",paragraphs:["You can see and change what is on your profile at any time.","Nothing a document says lands on your profile by itself. Every value we read out is shown to you first, with the page it came from, and you confirm it, correct it, or reject it.","You can delete any document you uploaded.","You can decline to answer any question. The only cost of leaving something blank is that we cannot check the programs that depend on it, and we will tell you which ones those are rather than quietly dropping them off your list.","You can ask us for a copy of what we hold about you, ask us to correct it, or ask us to delete it and close your account. Write to the address at the bottom of this page and a person will answer.","If we email you about funding matches, every message has an unsubscribe link, it works, and we act on it. You can also just tell us to stop.","Nothing about you goes to a lender, a grantor, or any other funder unless you pick that funder and say yes."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT in that file's section 4 table."},{id:"cookies",heading:"Cookies and analytics",paragraphs:["We do not run analytics on you. There is no Google Analytics, no tag manager, no session recorder, no advertising pixel and no third-party tracker on this site, and a test in our build fails if anyone adds one.","We do not set tracking cookies. When you sign in, the token that keeps you signed in is kept in your browser's own local storage, not in a cookie.","Two kinds of cookie can still reach you and neither of them follows you around the internet. Our hosting provider sets cookies to keep the site running and to block abusive traffic. Where a page sits behind a sign-in gate, that gate sets a cookie so it remembers you got through.","We do not sell information about you, and we do not share it with advertisers."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT in that file's section 4 table."},{id:"changes",heading:"Changes to this policy",paragraphs:["This policy will change, because the product is still being built. The date at the top of the page is the date of the version you are reading.","When we change something that matters, we will say what changed rather than quietly posting a new version. Every earlier version stays in our records; write to us with the date you have in mind and we will send you the version that was in effect then.","We will not apply a new rule backwards to information you already gave us. If we ever want to use what we already hold in a way this policy did not describe when you gave it to us, we will ask you first and you can say no.","If you do not like a change, you can ask us to delete your account and what is in it."],source:"DAV-09/10, dav-09-10-sections-2026-09-21.md (lending-compliance, Warren), verbatim; publish verdict PUBLISH TONIGHT in that file's section 4 table. Archive clause per regulatory-counsel 2026-10-24 (rulings/privacy-old-versions-2026-10-24.md); git log --follow on the policy source reaches a6113851 (2026-08-25), the first public version."}]).filter(e=>e.thin).map(e=>`privacy:${e.id}`),...r.filter(e=>e.thin).map(e=>`terms:${e.id}`)]},9373:(e,t,a)=>{a.d(t,{A:()=>d});var n=a(5155),o=a(8500),i=a.n(o),s=a(7855),r=a(2538);function d({className:e="text-sm"}){return(0,r.h)()?null:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(i(),{href:"/settings",className:`quiet-link min-h-11 inline-flex shrink-0 items-center whitespace-nowrap ${e}`.trim(),"data-testid":"settings-link",children:"Settings"}),(0,n.jsx)(s.A,{className:e})]})}}}]);